H.circle(pcx, pcy, pr, { fill: H.colors.panel, stroke: H.colors.accent, width: 3 });
H.circle(pcx, pcy, 5, { fill: H.colors.ink });
const lx = pcx - pr, rx = pcx + pr;
const amp = 70;
