const y1 = 250 - disp;
const y2 = 250 + disp;
H.line(lx, pcy, lx, y1, { color: H.colors.sub, width: 2 });
H.line(rx, pcy, rx, y2, { color: H.colors.sub, width: 2 });
function box(x, y, mass, col) {
  const s = 30 + 26 * H.clamp(mass / 10, 0, 1);
  H.rect(x - s / 2, y, s, s, { fill: H.colors.panel, stroke: col, width: 2, radius: 5 });
  H.text(mass.toFixed(1) + "kg", x, y + s / 2, { color: H.colors.ink, size: 12, align: "center", baseline: "middle" });
}
box(lx, y1, m1, H.colors.accent2);
box(rx, y2, m2, H.colors.good);
const sc = 1.4;
